       ELSE TO_CHAR(LOCATION_ID)     END                                                       AS \"Location Name\",     QTY_ORDERED                                               AS \"Quantity Ordered\",     QTY_RECEIVED                                              AS \"Quantity Received\",     QTY_ORDERED - QTY_RECEIVED                               AS \"Quantity Outstanding\",     UNIT_COST                                                 AS \"Unit Cost\",     ROUND(TOTAL_ORDERED_COST_RAW, 2)                         AS \"Total Ordered Cost\",     ROUND(TOTAL_RECEIVED_COST_RAW, 2)                        AS \"Total Received Cost\",     ROUND(TOTAL_ORDERED_COST_RAW - TOTAL_RECEIVED_COST_RAW, 2)                                                               AS \"Outstanding Cost\",     VENDOR_PRODUCT_NO                                         AS \"Vendor Product Number\",     SUPP_PACK_SIZE                                            AS \"Supplier Pack Size\"  FROM (

