"Supplier ID\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"1\"},{\"id\":\"3\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Department Number\"],\"expressionSourceColumns\":[\"Department Number\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Department Number\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Department Number\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"2\"},{\"id\":\"4\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Class Number\"],\"expressionSourceColumns\":[\"Class Number\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Class Number\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Class Number\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"3\"},{\"id\":\"5\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Subclass Number\"],\"expressionSourceColumns\":[\"Subclass Number\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Subclass Number\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Subclass Number\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"4\"},{\"id\":\"6\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Location ID\"],\"expressionSourceColumns\":[\"Location ID\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Location ID\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Location ID\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"5\"}],\"recommendations\":[],\"dataSubsetInfos\":{\"queryEditMode\":1,\"filterbarSettings\":{},\"uiSqlStatement\":\"

-- ── Query 3 ────────────────────────────────────────────────────────────
SELECT\\n        TRUNC(SYSDATE)                                        AS REPORT_DATE,\\n        oh.ORDER_NO                                           AS PO_NUMBER,\\n        oh.WRITTEN_DATE                                       AS PO_WRITTEN_DATE,\\n        oh.NOT_BEFORE_DATE                                    AS NOT_BEFORE_DATE,\\n        oh.NOT_AFTER_DATE                                     AS NOT_AFTER_DATE,\\n        oh.STATUS                                             AS PO_STATUS,\\n        oh.ORDER_TYPE                                         AS ORDER_TYPE,\\n        oh.CURRENCY_CODE                                      AS CURRENCY_CODE,\\n        oh.SUPPLIER                                           AS SUPPLIER_ID,\\n        sp.SUP_NAME                                           AS SUPPLIER_NAME,\\n        ol.ITEM                                               AS ITEM_ID,\\n        im.ITEM_DESC                                          AS ITEM_DESCRIPTION,\\n        im.DEPT                                               AS DEPT_NO,\\n        d.DEPT_NAME                                           AS DEPT_NAME,\\n        im.CLASS                                              AS CLASS_NO,\\n        c.CLASS_NAME                                          AS CLASS_NAME,\\n        im.SUBCLASS                                           AS SUBCLASS_NO,\\n        sc.SUB_NAME                                           AS SUBCLASS_NAME,\\n        ol.LOCATION                                           AS LOCATION_ID,\\n        ol.LOC_TYPE                                           AS LOC_TYPE,\\n        st.STORE_NAME                                         AS STORE_NAME,\\n        wh.WH_NAME                                            AS WH_NAME,\\n        NVL(ol.QTY_ORDERED, 0)                               AS QTY_ORDERED,\\n        NVL(ol.QTY_RECEIVED, 0)                              AS QTY_RECEIVED,\\n        ol.UNIT_COST                                          AS UNIT_COST,\\n        NVL(ol.QTY_ORDERED, 0)  * NVL(ol.UNIT_COST, 0)      AS TOTAL_ORDERED_COST_RAW,\\n        NVL(ol.QTY_RECEIVED, 0) * NVL(ol.UNIT_COST, 0)      AS TOTAL_RECEIVED_COST_RAW,\\n        os.REF_ITEM                                           AS VENDOR_PRODUCT_NO,\\n        os.SUPP_PACK_SIZE                                     AS SUPP_PACK_SIZE\\n\\n    FROM  MFCS_RDS.RDS_WV_ORDHEAD                 oh\\n    JOIN  MFCS_RDS.RDS_WV_ORDLOC                  ol   ON  oh.ORDER_NO = ol.ORDER_NO\\n    JOIN  MFCS_RDS.RDS_WV_ORDSKU                  os   ON  ol.ORDER_NO = os.ORDER_NO\\n                                                      AND  ol.ITEM     = os.ITEM\\n    JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER             im   ON  ol.ITEM     = im.ITEM\\n    JOIN  MFCS_RDS.RDS_WV_DEPS                    d    ON  im.DEPT     = d.DEPT\\n    JOIN  MFCS_RDS.RDS_WV_CLASS                   c    ON  im.DEPT     = c.DEPT\\n                                                      AND  im.CLASS    = c.CLASS\\n    JOIN  MFCS_RDS.RDS_WV_SUBCLASS                sc   ON  im.DEPT     = sc.DEPT\\n                                                      AND  im.CLASS    = sc.CLASS\\n                                                      AND  im.SUBCLASS = sc.SUBCLASS\\n    LEFT JOIN MFCS_RDS.RDS_WV_SUPS                sp   ON  oh.SUPPLIER = sp.SUPPLIER\\n    LEFT JOIN MFCS_RDS.RDS_WV_STORE               st   ON  ol.LOCATION = st.STORE\\n    LEFT JOIN MFCS_RDS.RDS_WV_WH                  wh   ON  ol.LOCATION = wh.WH\\n\\n    WHERE\\n        oh.WRITTEN_DATE &gt;= ADD_MONTHS(SYSDATE, -3)\\n)\\n\\n\"},\"editorCurrentState\":false,\"joins\":{\"tables\":[]}}</ds:uiOptions><ds:version>v5</ds:version></ds:datasetImportOptions>","business-model":"\"\"","active":true,"custom-attrs":"{\"src_parquet_verified\":\"true\"}","description":"External dataset","display-name":"Manual Query","locale":"sys","is-user-striped":false,"file-length":0,"type":"sql","properties-last-modified":"2026-07-29T16:57:41.696+0000","connection-namespace":"disadmin_disadmin_APPID","private-connection":false,"credential-exists":true,"connection-name":"Remote RDS MFCS Connection","provider-type":"db","provider-name":"oracle","sso-enabled":false,"datamodelname":"'ReCommon'.'RPT_096_Buying_Report'","parent-namespace":"ReCommon","parent-name":"RPT_096_Buying_Report","data-access-mode":"auto","is-data-cacheable":true,"checkpoint-metadata-stale":false,"owner-guid":"ReCommon","is-temporary":false},"datasetType":"EMBEDDED","datamodelTwoPartName":"'ReCommon'.'RPT_096_Buying_Report'"}
